def get_number():
    """Get a number from user input."""
    while True:
        try:
            num = float(input("Enter a number: "))
            return num
        except ValueError:
            print("That's not a valid number. Please try again.")

def perform_operation(num1, num2, operator):
    """Perform a basic arithmetic operation based on the given operator."""
    if operator == "+":
        return num1 + num2
    elif operator == "-":
        return num1 - num2
    elif operator == "*":
        return num1 * num2
    elif operator == "/":
        if num2 == 0:
            raise ValueError("Cannot divide by zero.")
        return num1 / num2
    else:
        raise ValueError("Invalid operator. Please use +, -, *, or /.")

def main():
    """Get user input, perform the operation, and display the result."""
    num1 = get_number()
    operator = input("Enter an operator (+, -, *, or /): ")
    num2 = get_number()

    try:
        result = perform_operation(num1, num2, operator)
        print(f"{num1} {operator} {num2} = {result}")
    except ValueError as e:
        print(e)

if __name__ == "__main__":
    main()
```

This program defines four functions: `get_number()` to get a number from user input, `perform_operation()` to perform the arithmetic operation based on the given operator, `main()` to get user input, perform the operation, and display the result, and `main()` to call the other functions and run the program.
